static double polyvalAK2( double r );

/**
* Implementation of the high order Newton-like method.
*/
static double higherNewton( double x0, double a, int m, double p, double q, double lgama, double invfp, bool pcase ) {
	double dlnr;
	double xini;
	double ck0;
	double ck1;
	double ck2;
	double a2;
	double x2;
	double px;
	double qx;
	double xr;
	double t;
	int n;
	double r;
	double x;

	x = x0;
	t = 1.0;
	n = 1;
	a2 = a * a;
	xini = x0;
	do {
		x = x0;
		x2 = x * x;
		if ( m == 0 ) {
			dlnr = ( ( 1.0 - a ) * stdlib_base_ln( x ) ) + x + lgama;
			if ( dlnr > stdlib_base_ln(MAX_FLOAT32) ) {
				return xini;
			}
			r = stdlib_base_exp( dlnr );
		} else {
			r = -invfp * x;
		}
		if ( pcase ) {
			px = stdlib_base_gammainc( x, a, true, false );
			ck0 = -r * ( px - p );
		} else {
			qx = stdlib_base_gammainc( x, a, true, true );
			ck0 = r * ( qx - q );
		}
		r = ck0;
		if ( ( p > 1e-120 ) || ( n > 1 ) ) {
			ck1 = 0.5 * ( x - a + 1.0 ) / x;
			ck2 = ( (2.0*x2) - (4.0*x*a) + (4.0*x) + (2.0*a2) - (3.0*a) + 1.0 ) / x2;
			ck2 /= 6.0;
			x0 = x + ( r * ( 1.0 + ( r * ( ck1 + (r*ck2) ) ) ) );
		} else {
			x0 = x + r;
		}
		t = stdlib_base_abs( ( x/x0 ) - 1.0 );
		n += 1;
		x = x0;
		if ( x < 0.0 ) {
			x = xini;
			n = 100;
		}
	} while ( ( ( t > 2e-14 ) && ( n < 35 ) ) );
	xr = x > 0.0 ? x : 0.0;
	return xr;
}

/**
* Returns the positive number satisfying \( \eta^2/2=\lambda-1-\ln(\lambda) \) with \( \operatorname{sign}(\lambda-1)=\operatorname{sign}(\eta) \).
*/
static double lambdaeta( double eta ) {
	double L2, L3, L4, L5;
	double la;
	double L;
	double q, r, s;
	static const double THRESHOLD = 1.0e-8;
	static const double ONEO12 = 0.08333333333333333;
	static const double ONEO120 = 0.008333333333333333;
	double AK[6];

	s = eta * eta * 0.5;
	if ( eta == 0.0 ) {
		la = 0.0;
	}
	else if ( eta < -1.0 ) {
		r = stdlib_base_exp( -1.0 - s );
		la = polyvalAK1( r );
	}
	else if ( eta < 1.0 ) {
		r = eta;
		la = polyvalAK2( r );
	}
	else {
		r = 11.0 + s;
		L = stdlib_base_ln( r );
		la = r + L;
		r = 1.0 / r;
		L2 = L * L;
		L3 = L2 * L;
		L4 = L3 * L;
		L5 = L4 * L;
		AK[0] = 1.0;
		AK[1] = ( 2.0-L ) * 0.5;
		AK[2] = ( ( -9.0*L ) + 6.0 + ( 2.0*L2 ) ) / 6.0;
		AK[3] = -( (3.0*L3)+ (36.0*L) - (22.0*L2) - 12.0 ) * ONEO12;
		AK[4] = ( 60.0 + (350.0*L2) - (300.0*L) - (125.0*L3) + (12.0*L4) ) / 60.0;
		AK[5] = -(-120.0 - (274.0*L4) + (900.0*L) - (1700.0*L2) + (1125.0*L3) + (20.0*L5)) * ONEO120;
		la += ( L * r * evalpoly(AK, 6, r) );
	}
	r = 1.0;
	if (
		( eta > -3.5 && eta < -0.03 ) ||
		( eta > 0.03 && eta < 40.0 )
	) {
		r = 1.0;
		q = la;
		do {
			la = q * ( s+stdlib_base_ln(q) ) / ( q-1.0 );
			r = stdlib_base_abs( ( q/la ) - 1.0 );
			q = la;
		} while ( r > THRESHOLD );
	}
	return la;
}

static double polyvalAK1( double r ) {
	static const double ak1[] = {
		3.183098861837907e-01, 2.705633337418241e-02, 1.239335416533316e-03,
		2.583338384581978e-05, -3.101829763300332e-07, -1.588693874366961e-08,
		-1.378786850299244e-09
	};
	return evalpoly(ak1, 7, r);
}

static double polyvalAK2( double r ) {
	static const double ak2[] = {
		1.0, 1.0, 0.3333333333333333, 0.0, -0.06666666666666667,
		-0.03555555555555555, 0.030476190476190474, 0.021547619047619047,
		-0.02230842230842231, -0.018617195767195767, 0.020296245962459623
	};
	return evalpoly(ak2, 11, r);
}

/**
* Computes the regulated gamma function.
*/
static double gamstar( double x ) {
	if ( x >= 3.0 ) {
		return stdlib_base_exp( stirling(x) );
	}
	if ( x > 0.0 ) {
		return stdlib_base_gamma(x) / ( stdlib_base_exp( -x + ( ( x-0.5 ) * stdlib_base_ln(x) ) ) * SQRT_TWO_PI );
	}
	return MAX_FLOAT32;
}

static double stirling( double x ) {
	static const double C[] = {
		0.08333333333333333, -0.002777777777777778, 0.0007936507936507936,
		-0.0002755731922398589, 0.0001309838779518041, -0.00008129533379969938
	};
	double y = 1.0 / x;
	double y2 = y * y;
	return evalpoly(C, 6, y2) * y;
}

/**
* Evaluates the `eps1` function.
*/
static double eps1( double eta ) {
	double la;
	if ( stdlib_base_abs( eta ) < 1.0 ) {
		return rateval( eta );
	}
	la = lambdaeta( eta );
	return stdlib_base_ln( eta / ( la - 1.0 ) ) / eta;
}

static double rateval( double eta ) {
	static const double ak0[] = {
		-0.3333333333333333, -0.08333333333333333, 0.014814814814814815,
		-0.0011574074074074074, -0.0003527336860670194, 0.0001787551440329218
	};
	static const double bk0[] = {
		1.0, -0.75, 0.3541666666666667, -0.10677083333333333,
		0.021085069444444443, -0.0028741319444444446
	};
	double p = evalpoly(ak0, 6, eta);
	double q = evalpoly(bk0, 6, eta);
	return p / q;
}

/**
* Evaluates the `eps2` function.
*/
static double eps2( double eta ) {
	double lnmeta;
	double x;
	if ( eta < -5.0 ) {
		x = eta * eta;
		lnmeta = stdlib_base_ln( -eta );
		return ( 12.0 - x - ( 6.0*( lnmeta*lnmeta ) ) ) / ( 12.0*x*eta );
	}
	if ( eta < -2.0 ) {
		return rateval1( eta );
	}
	if ( eta < 2.0 ) {
		return rateval2( eta );
	}
	if ( eta < 1000.0 ) {
		x = 1.0 / eta;
		return rateval3( eta ) / ( -12.0*eta );
	}
	return -1.0 / ( 12.0 * eta );
}

static double rateval1( double eta ) {
	static const double ak1[] = {
		-0.001851851851851852, 0.003472222222222222, -0.0026455026455026454,
		0.0009902263374485596
	};
	static const double bk1[] = { 1.0, -1.5, 0.875, -0.21875 };
	double p = evalpoly(ak1, 4, eta);
	double q = evalpoly(bk1, 4, eta);
	return p / q;
}

static double rateval2( double eta ) {
	static const double ak2[] = {
		-0.041666666666666664, 0.0, 0.00496031746031746, 0.0,
		-0.0006231481481481482
	};
	static const double bk2[] = { 1.0, 0.0, -0.4166666666666667, 0.0, 0.05753968253968254 };
	double p = evalpoly(ak2, 5, eta);
	double q = evalpoly(bk2, 5, eta);
	return p / q;
}

static double rateval3( double eta ) {
	static const double ak3[] = {
		1.0, -0.15, 0.03, -0.007291666666666667, 0.0020416666666666668
	};
	return evalpoly(ak3, 5, 1.0/eta);
}

/**
* Evaluates the `eps3` function.
*/
static double eps3( double eta ) {
	double x;
	double y;

	if ( eta < -8.0 ) {
		x = eta * eta;
		y = stdlib_base_ln( -eta ) / eta;
		return ( -30.0 + ( eta*y*( (6.0*x*y*y)-12.0+x ) ) ) / ( 12.0*eta*x*x );
	}
	if ( eta < -4.0 ) {
		return rational1( eta ) / ( eta*eta );
	}
	if ( eta < -2.0 ) {
		return rational2( eta );
	}
	if ( eta < 2.0 ) {
		return rational3( eta );
	}
	if ( eta < 10.0 ) {
		x = 1.0 / eta;
		return rational4( x ) / ( eta*eta );
	}
	if ( eta < 100.0 ) {
		x = 1.0 / eta;
		return rational5( x ) / ( eta*eta );
	}
	return -stdlib_base_ln( eta ) / ( 12.0*eta*eta*eta );
}

static double rational1( double eta ) {
	static const double ak4[] = { -0.0006494341563786008, 0.00022947209362139917 };
	static const double bk4[] = { 1.0, -1.0, 0.25 };
	double p = evalpoly(ak4, 2, eta);
	double q = evalpoly(bk4, 3, eta);
	return p / q;
}

static double rational2( double eta ) {
	static const double ak5[] = {
		-0.0008618882909167117, -0.0007840392217200666, -0.0002990724803031902
	};
	static const double bk5[] = { 1.0, -1.5, 0.875, -0.21875 };
	double p = evalpoly(ak5, 3, eta);
	double q = evalpoly(bk5, 4, eta);
	return p / q;
}

static double rational3( double eta ) {
	static const double ak6[] = {
		0.005952380952380952, 0.0, -0.0011904761904761906, 0.0,
		0.00024195767195767195
	};
	static const double bk6[] = {
		1.0, 0.0, -0.8333333333333334, 0.0, 0.20634920634920634
	};
	double p = evalpoly(ak6, 5, eta);
	double q = evalpoly(bk6, 5, eta);
	return p / q;
}

static double rational4( double x ) {
	static const double ak7[] = {
		-0.0005313079364639922, 0.0005921664373536939, -0.0002708782096718045
	};
	static const double bk7[] = { 1.0, 0.25, 0.025, 0.0015625 };
	double p = evalpoly(ak7, 3, x);
	double q = evalpoly(bk7, 4, x);
	return p / q;
}

static double rational5( double x ) {
	static const double ak8[] = {
		-0.00034436760689237765, 0.00005171790908260592, 0.00033493161081142234
	};
	static const double bk8[] = { 1.0, 0.15, 0.009375, -0.0001953125 };
	double p = evalpoly(ak8, 3, x);
	double q = evalpoly(bk8, 4, x);
	return p / q;
}

static double evalpoly( const double c[], int n, double x ) {
	double r = c[n-1];
	for (int i = n - 2; i >= 0; --i) {
		r = r * x + c[i];
	}
	return r;
}

/**
* Computes `x` in the equations `P(a,xr) = p` and `Q(a,xr) = q`, where `a` is a positive parameter and `p` and `q` satisfy `p+q = 1`.
*/
static double compute( double a, double p, double q ) {
	double ap1inv;
	double invfp;
	double lgama;
	bool pcase;
	double porq;
	double ainv;
	double logr;
	double ap22, ap14, ap13, ap12;
	double vgam, vmin, xini, ap1, ap2, ap3, eta, p6, p5, x0, a2, L2, L3, L4, b2, b3, p3, a4, fp, p4, p2, a3, xr, b, L;
	int i, k, m;
	double r, s, t, y;
	double CK[ 5 ];

	if ( p < 0.5 ) {
		pcase = true;
		porq = p;
		s = -1.0;
	} else {
		pcase = false;
		porq = q;
		s = 1.0;
	}
	k = 0;
	if ( stdlib_base_abs( a-1.0 ) < 1.0e-4 ) {
		m = 0;
		if ( pcase ) {
			if ( p < 1.0e-3 ) {
				p2 = p * p;
				p3 = p2 * p;
				p4 = p3 * p;
				p5 = p4 * p;
				p6 = p5 * p;
				x0 = p + ( p2*0.5 ) + ( p3*(1.0/3.0) ) + ( p4*0.25 ) + ( p5*0.2 ) + ( p6*(1.0/6.0) );
			} else {
				x0 = -stdlib_base_ln( 1.0-p );
			}
		} else {
			x0 = -stdlib_base_ln( q );
		}
		if ( a == 1.0 ) {
			k = 2;
			xr = x0;
		} else {
			lgama = stdlib_base_gammaln( a );
			k = 1;
		}
	}
	if ( q < 1.0e-30 && a < 0.5 ) {
		m = 0;
		x0 = -stdlib_base_ln( q*stdlib_base_gamma(a) ) + ( ( a-1.0 ) * stdlib_base_ln( -stdlib_base_ln( q*stdlib_base_gamma(a) ) ) );
		k = 1;
		lgama = stdlib_base_gammaln( a );
	}
	if ( a > 1.0 && a < 500.0 && p < 1.0e-80 ) {
		m = 0;
		ainv = 1.0 / a;
		ap1inv = 1.0 / ( a+1.0 );
		x0 = ( stdlib_base_gammaln( a+1.0 ) + stdlib_base_ln( p ) ) * ainv;
		x0 = stdlib_base_exp( x0 );
		xini = x0;
		for ( i = 0; i < 10; i++ ) {
			x0 = xini * stdlib_base_exp( x0*ainv ) * stdlib_base_pow( 1.0-( x0*ap1inv ), ainv );
		}
		k = 1;
		lgama = stdlib_base_gammaln( a );
	}

	logr = (1.0/a) * ( stdlib_base_ln(p) + stdlib_base_gammaln( a+1.0 ) );
	if ( ( logr < stdlib_base_ln( 0.2 * ( 1.0+a ) ) ) && ( k == 0 ) ) {
		r = stdlib_base_exp( logr );
		m = 0;
		a2 = a * a;
		a3 = a2 * a;
		a4 = a3 * a;
		ap1 = a + 1.0;
		ap12 = ap1 * ap1;
		ap13 = ap1 * ap12;
		ap14 = ap12 * ap12;
		ap2 = a + 2.0;
		ap22 = ap2 * ap2;
		ap3 = a + 3.0;
		CK[ 0 ] = 1.0;
		CK[ 1 ] = 1.0 / ap1;
		CK[ 2 ] = 0.5 * ( ( 3.0*a ) + 5.0 ) / ( ap12*ap2 );
		CK[ 3 ] = (1.0/3.0) * ( 31.0 + (8.0*a2) + (33.0*a) ) / ( ap13*ap2*ap3 );
		CK[ 4 ] = (1.0/24.0) * ( 2888.0 + (1179.0*a3) + (125.0*a4) + (3971.0*a2) + (5661.0*a) ) / ( ap14*ap22*ap3*( a+4.0 ) );
		x0 = r * evalpoly( CK, 5, r );
		lgama = stdlib_base_gammaln( a );
		k = 1;
	}
	if ( ( a < 10.0 ) && ( k == 0 ) ) {
		vgam = stdlib_base_sqrt( a ) / ( gamstar(a)*SQRT_TWO_PI );
		vmin = stdlib_base_min( 0.02, vgam );
		if ( q < vmin ) {
			m = 0;
			b = 1.0 - a;
			b2 = b * b;
			b3 = b2 * b;
			eta = stdlib_base_sqrt( -2.0/a * stdlib_base_ln( q/vgam ) );
			x0 = a * lambdaeta( eta );
			L = stdlib_base_ln( x0 );
			if ( x0 > 5.0 ) {
				L2 = L * L;
				L3 = L2 * L;
				L4 = L3 * L;
				r = 1.0 / x0;
				CK[ 0 ] = L - 1.0;
				CK[ 1 ] = ( (3.0*b) - (2.0*b*L) + L2 - ( 2.0*L ) + 2.0 ) * 0.5;
				CK[ 2 ] =( (24.0*b*L) - (11.0*b2) - (24.0*b) - (6.0*L2) + (12.0*L) - 12.0 - (9.0*b*L2) + (6.0*b2*L) + (2.0*L3) ) * (1.0/6.0);
				CK[ 3 ] = ( (-12.0*b3*L) + (8.04*b*L2) - (114.0*b2*L) + (72.0+(36.0*L2)) + (((3.0*L4)-(72.0*L)+162.0) * (b-(168.0*b*L))) - ((12.0*L3)+(25.0*b3)) - ( (22.0*b*L3)+(36.0*b2*L2)+(120.0*b2) ) ) * (1.0/12.0);
				CK[ 4 ] = 0.0;
				x0 = x0 - L + ( b*r*evalpoly( CK, 5, r ) );
			} else {
				r = 1.0 / x0;
				L2 = L * L;
				t = L - (b*r*(L-1.0));
				if ( t < x0 ) {
					x0 -= t;
				}
			}
			lgama = stdlib_base_gammaln( a );
			k = 1;
		}
	}
	if ( ( stdlib_base_abs( porq-0.5 ) < 1.0e-5 ) && ( k == 0 ) ) {
		m = 0;
		ainv = 1.0 / a;
		x0 = a - (1.0/3.0) + ( ( 0.019753086419753086 +
			( 0.0072114442484812855 * ainv ) ) * ainv );
		lgama = stdlib_base_gammaln( a );
		k = 1;
	}
	if ( ( a < 1.0 ) && ( k == 0 ) ) {
		m = 0;
		if ( pcase ) {
			x0 = stdlib_base_exp( (1.0/a) * ( stdlib_base_ln(porq) + stdlib_base_gammaln(a+1.0) ) );
		} else {
			x0 = stdlib_base_exp( (1.0/a) * ( stdlib_base_ln(1.0-porq) + stdlib_base_gammaln(a+1.0) ) );
		}
		lgama = stdlib_base_gammaln( a );
		k = 1;
	}
	if ( k == 0 ) {
		m = 1;
		ainv = 1.0 / a;
		r = stdlib_base_erfcinv( 2.0 * porq );
		eta = s * r / stdlib_base_sqrt( a*0.5 );
		if ( r < MAX_FLOAT32 ) {
			eta += ( eps1(eta) + ( (eps2(eta)+(eps3(eta)*ainv))*ainv ) ) * ainv;
			x0 = a * lambdaeta(eta);
			y = eta;
			fp = -stdlib_base_sqrt( a/TWO_PI ) * stdlib_base_exp( -0.5*a*y*y ) / ( gamstar(a) );
			invfp = 1.0 / fp;
		} else {
			return 0.0/0.0;
		}
	}
	if ( k < 2 ) {
		xr = higherNewton( x0, a, m, p, q, lgama, invfp, pcase );
	}
	return xr;
}

/**
* Inverts the lower gamma function; i.e., computes `xr` such that `P(a,xr) = p`.
*/
double stdlib_base_gammaincinv( const double p, const double a, const bool upper ) {
	if ( stdlib_base_is_nan( p ) || stdlib_base_is_nan( a ) ) {
		return 0.0 / 0.0; // NaN
	}
	if ( a < SMALLEST_NORMAL_FLOAT32 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( p > 1.0 || p < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	// Case: invert upper gamma function
	if ( upper ) {
		if ( p == 0.0 ) {
			return PINF;
		}
		if ( p == 1.0 ) {
			return 0.0;
		}
		return compute( a, 1.0 - p, p );
	}
	// Default: invert lower gamma function
	if ( p == 0.0 ) {
		return 0.0;
	}
	if ( p == 1.0 ) {
		return PINF;
	}
	return compute( a, p, 1.0 - p );
}
